import{_ as m,C as o,o as b,c as v,j as t,a,E as s,a8 as f}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/gDRCpTMCqEU-640.webp",k="/schedule-dashboard/thumbs/yt/gDRCpTMCqEU-1280.webp",n="/schedule-dashboard/thumbs/yt/U7ZYBCcdJPg-640.webp",y="/schedule-dashboard/thumbs/yt/U7ZYBCcdJPg-1280.webp",i="/schedule-dashboard/thumbs/yt/-a2oTS9J67U-640.webp",_="/schedule-dashboard/thumbs/yt/-a2oTS9J67U-1280.webp",l="/schedule-dashboard/thumbs/yt/3ZlQk4-knWM-640.webp",S="/schedule-dashboard/thumbs/yt/3ZlQk4-knWM-1280.webp",h="/schedule-dashboard/thumbs/yt/Fe4aSMXsOZ4-640.webp",T="/schedule-dashboard/thumbs/yt/Fe4aSMXsOZ4-1280.webp",c="/schedule-dashboard/thumbs/yt/SHvwutPSeZg-640.webp",P="/schedule-dashboard/thumbs/yt/SHvwutPSeZg-1280.webp",d="/schedule-dashboard/thumbs/yt/dYh7TQkuYFE-640.webp",A="/schedule-dashboard/thumbs/yt/dYh7TQkuYFE-1280.webp",p="/schedule-dashboard/thumbs/yt/RsWyIQoJkHY-640.webp",I="/schedule-dashboard/thumbs/yt/RsWyIQoJkHY-1280.webp",w="/schedule-dashboard/thumbs/yt/BjmoXpgbfhQ-640.webp",M="/schedule-dashboard/thumbs/yt/BjmoXpgbfhQ-1280.webp",N=JSON.parse('{"title":"AI Digest · Wed 14 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-14","routine":"digest"},"relativePath":"digest/2026-10-14.md","filePath":"digest/[date].md"}'),C={name:"digest/2026-10-14.md"},E=r+" 640w, "+k+" 1280w",Z=n+" 640w, "+y+" 1280w",R=i+" 640w, "+_+" 1280w",B=l+" 640w, "+S+" 1280w",Y=h+" 640w, "+T+" 1280w",J=c+" 640w, "+P+" 1280w",U=d+" 640w, "+A+" 1280w",q=p+" 640w, "+I+" 1280w",x=w+" 640w, "+M+" 1280w",Q={id:"ai-digest-·-wed-14-oct-2026",tabindex:"-1"};function W(F,e,D,H,O,X){const u=o("Badge"),g=o("DayFilter");return b(),v("div",null,[t("h1",Q,[e[0]||(e[0]=a("AI Digest · Wed 14 Oct 2026 ",-1)),s(u,{type:"tip",text:"9"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-wed-14-oct-2026","aria-label":'Permalink to "AI Digest · Wed 14 Oct 2026 <Badge type="tip" text="9" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack, last 24h (14 Oct 2026) · run date Wed 14 Oct 2026 · 9 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer"),a(` posted 7 new talks (about 1.6 hours). The freshest is "What Technical Due Diligence Finds When the Deck Says '70% Automated'" (6 min, and sharp). The most original are EXL's graph-neural-network fraud model (27–33% lift, 3 ms P99) and Corey Gallon's three-level agent review method, with Jellyfish's "Tokens Are the Cheap Part" adding rare cost-per-PR data. The Grant and Gayle talks overlap: both are governance and autonomy-ladder playbooks for regulated enterprises, so skim one. All 7 had full transcripts.`)]),t("p",null,[t("strong",null,"Better Stack"),a(` posted no full videos, only 2 Shorts: an F1 "production incident" story (a wet-weather software bug hotfixed mid-race) and a 2-minute recap of yesterday's Universal Modder video, which is mostly a repeat.`)]),t("p",null,[t("em",null,"Only Shorts were uploaded in the last 24h (no full-length videos), so they are included briefly.")])],-1)),s(g),e[5]||(e[5]=f('<div class="grid cards2"><article class="it full" id="v-gDRCpTMCqEU" data-title="What Technical Due Diligence Finds When the Deck Says “70% Automated” — Soukaïna Abelhad" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=gDRCpTMCqEU" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+E+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=gDRCpTMCqEU" target="_blank" rel="noopener">What Technical Due Diligence Finds When the Deck Says “70% Automated” — Soukaïna Abelhad</a></h3><div class="meta">AI Engineer · Soukaïna Abelhad (AI tech lead) · uploaded 13 Oct, 11:30 PM IST · 6:29</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — 6 tight minutes, and a good BS-detector for any &quot;X% automated&quot; claim.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 25 times before. New here: applied as an investor diligence test, citing Meta&#39;s 24-point gap between an automated grader and human merge decisions.</div><div class="sh">Check 1: arithmetic</div><ul><li><strong>Context for headline numbers:</strong> The famous &quot;55.8% faster&quot; comes from 95 developers building one JS HTTP server against 12 visible tests (<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=5s" target="_blank" rel="noopener">0:05</a>–<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=60s" target="_blank" rel="noopener">1:00</a>)</li><li><strong>Workload vs labour:</strong> In Faros data from 10,000+ developers across 1,255 teams, high-adoption teams merged 98% more PRs, but review time rose 91% and PRs got 154% larger. If human labour (reviewers, trainers, escalations, rework) tracks volume, that&#39;s assistance, not labour removal (<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=67s" target="_blank" rel="noopener">1:07</a>–<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=131s" target="_blank" rel="noopener">2:11</a>)</li></ul><div class="sh">Check 2: definition</div><ul><li><strong>AI-attributed ≠ autonomous:</strong> Uber says 70% of its PRs are AI-attributed, but that doesn&#39;t give an autonomous rate. Use the ladder AI-drafted → human-edited → human-approved → no human (&quot;straight-through processing&quot;) inside a named boundary (<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=131s" target="_blank" rel="noopener">2:11</a>–<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=186s" target="_blank" rel="noopener">3:06</a>)</li></ul><div class="sh">Check 3: evaluation</div><ul><li><strong>Graders vs humans:</strong> Meta found a 24-point gap between an automated grader and maintainers&#39; merge decisions on 296 blind-reviewed AI PRs. In her own project, 10/10 outputs passed automated validation and &quot;barely few&quot; survived experts. Ask who labelled the ground truth and what escaped (<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=186s" target="_blank" rel="noopener">3:06</a>–<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=253s" target="_blank" rel="noopener">4:13</a>)</li><li><strong>Builder.ai lesson:</strong> The WSJ questioned its AI claims in 2019, revenue was revised from $220M to ~$55M, and it filed Chapter 7. The warning existed, but no gate acted on it (<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=253s" target="_blank" rel="noopener">4:13</a>–<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=298s" target="_blank" rel="noopener">4:58</a>)</li><li><strong>Unit economics:</strong> Use cost per accepted autonomous task. Failures, escalations and rework count as cost (<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=298s" target="_blank" rel="noopener">4:58</a>–<a href="https://www.youtube.com/watch?v=gDRCpTMCqEU&amp;t=382s" target="_blank" rel="noopener">6:22</a>)</li></ul></div></article><article class="it full" id="v-U7ZYBCcdJPg" data-title="Tokens Are the Cheap Part — Steve Jamison, Jellyfish" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=U7ZYBCcdJPg" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+Z+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg" target="_blank" rel="noopener">Tokens Are the Cheap Part — Steve Jamison, Jellyfish</a></h3><div class="meta">AI Engineer · Steve Jamison, Jellyfish · uploaded 13 Oct, 10:30 PM IST · 17:32</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — rare hard numbers on AI coding ROI (observational, vendor data); the core argument is done by 9:26.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 40 times before. New here: a cost-per-merged-PR metric that adds salary and tokens, with spend-quintile data.</div><div class="sh">The headline tension</div><ul><li><strong>60× spend vs 43% output:</strong> AI costs are up 60× year over year, and merged PRs per engineer are up 43%, with throughput inflecting in early 2026 when spend jumped (<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=21s" target="_blank" rel="noopener">0:21</a>–<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=90s" target="_blank" rel="noopener">1:30</a>)</li><li><strong>Add salary to the cost model:</strong> &quot;Intelligence cost&quot; per PR is salary plus AI. AI is about 2.5% of the cost of a merged PR and salary about 97.5% (Aug 2026 data) (<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=177s" target="_blank" rel="noopener">2:57</a>–<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=248s" target="_blank" rel="noopener">4:08</a>)</li><li><strong>Cost per merged PR fell 26%:</strong> This happened despite the 60× AI cost rise, and 83% of companies studied saw a drop, because throughput spreads salary over more PRs (<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=248s" target="_blank" rel="noopener">4:08</a>–<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=302s" target="_blank" rel="noopener">5:02</a>)</li></ul><div class="sh">Spend groups</div><ul><li><strong>Quintiles:</strong> The lightest group spends about 0.3% of PR cost on AI (~60M tokens/dev/month) and the heaviest about 8.5% (~2.5B tokens/dev/month). Heavy spenders got +67% throughput vs ~40%, and −32% cost per PR vs ~−25% (<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=302s" target="_blank" rel="noopener">5:02</a>–<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=481s" target="_blank" rel="noopener">8:01</a>)</li><li><strong>Diminishing, not zero, returns:</strong> The top 10% of company-months used 8× the median tokens and had about 25% lower cost per PR (<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=481s" target="_blank" rel="noopener">8:01</a>–<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li><li><strong>Same developer, heavy weeks:</strong> About 2× token spend, 27% more merged PRs, and ~18% lower cost per PR (<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=612s" target="_blank" rel="noopener">10:12</a>)</li></ul><div class="sh">Quality checks and advice</div><ul><li><strong>Reverts and PR size:</strong> Revert rates dropped slightly (within noise), and PRs are getting bigger, not smaller, so the throughput gain isn&#39;t PR-splitting (<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=612s" target="_blank" rel="noopener">10:12</a>–<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=741s" target="_blank" rel="noopener">12:21</a>)</li><li><strong>Budget-season metric:</strong> Track total cost per merged PR monthly next to the AI bill and throughput, with reverts as a counterweight. Watch for runaway jobs, but don&#39;t make token caps the driving metric (<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=899s" target="_blank" rel="noopener">14:59</a>–<a href="https://www.youtube.com/watch?v=U7ZYBCcdJPg&amp;t=990s" target="_blank" rel="noopener">16:30</a>)</li></ul></div></article><article class="it full" id="v--a2oTS9J67U" data-title="The Agent Works. Does Anyone Trust It? — Michele Grant, Leading at Scale" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=-a2oTS9J67U" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+R+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=-a2oTS9J67U" target="_blank" rel="noopener">The Agent Works. Does Anyone Trust It? — Michele Grant, Leading at Scale</a></h3><div class="meta">AI Engineer · Michele Grant, Leading at Scale · uploaded 13 Oct, 9:30 PM IST · 15:05</div><div class="verdict v-skim"><b>Verdict:</b> skim — a solid governance checklist for leaders; engineers can jump to 9:57 for the logging and autonomy-stage parts.</div><div class="sh">Value before production</div><ul><li><strong>Three questions:</strong> What value does it create, who is on the hook, and what evidence permits more autonomy? Per agent, leadership decides what it may do, who owns it, what it records and what triggers escalation (<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=78s" target="_blank" rel="noopener">1:18</a>–<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=158s" target="_blank" rel="noopener">2:38</a>)</li><li><strong>Scenario:</strong> A $15B acquisition targeting $400M in synergies across 40 workstreams. An agent drafts the weekly steering-committee deck, and a 4-week pilot matches analysts line for line (<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=158s" target="_blank" rel="noopener">2:38</a>–<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=273s" target="_blank" rel="noopener">4:33</a>)</li><li><strong>Value case vs baseline:</strong> Cycle time (5→2 days), analyst capacity (80 h/week, which counts only if redeployed and net of compute, licence and review cost), and detection time from data slip to committee. No baseline means don&#39;t deploy (<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=273s" target="_blank" rel="noopener">4:33</a>–<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=392s" target="_blank" rel="noopener">6:32</a>)</li></ul><div class="sh">Accountability</div><ul><li><strong>Three lines model:</strong> The integration lead owns the output, risk/compliance challenge it, and internal audit assures it. A named senior analyst reviews daily with authority to override and a kill switch (<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=392s" target="_blank" rel="noopener">6:32</a>–<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=497s" target="_blank" rel="noopener">8:17</a>)</li><li><strong>Human Work Standard:</strong> A one-page map of every decision fork to the human role, evidence and escalation path. The agent prepares the analysis and stops there. A decision with no owner is the only reason to delay (<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=497s" target="_blank" rel="noopener">8:17</a>–<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=597s" target="_blank" rel="noopener">9:57</a>)</li></ul><div class="sh">Evidence for autonomy</div><ul><li><strong>Artifacts:</strong> A decision log (data, tool calls, prompt, model versions, sign-off), with core reconciliation math in deterministic finance-approved code rather than LLM prose. Plus a model inventory with regression triggers when the base model or a source API changes (<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=597s" target="_blank" rel="noopener">9:57</a>–<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=707s" target="_blank" rel="noopener">11:47</a>)</li><li><strong>Four stages:</strong> Shadow → supervised draft → exceptions plus random sample → exceptions only. In stage 4, track missed issues via independent sampling, because a falling override rate can mean review got shallower, not that the agent improved (<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=707s" target="_blank" rel="noopener">11:47</a>–<a href="https://www.youtube.com/watch?v=-a2oTS9J67U&amp;t=823s" target="_blank" rel="noopener">13:43</a>)</li></ul></div></article><article class="it full" id="v-3ZlQk4-knWM" data-title="Deploying AI Inside a Bank Is Not an Engineering Problem — Paden Gayle, Applied AI Engineers" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=3ZlQk4-knWM" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+B+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=3ZlQk4-knWM" target="_blank" rel="noopener">Deploying AI Inside a Bank Is Not an Engineering Problem — Paden Gayle, Applied AI Engineers</a></h3><div class="meta">AI Engineer · Paden Gayle (ex-Bloomberg/Google, forward-deployed engineer) · uploaded 13 Oct, 8:30 PM IST · 15:07</div><div class="verdict v-skim"><b>Verdict:</b> skim from 5:52 — useful checklist if you deploy into regulated orgs; the opening is slow and somewhat repetitive.</div><div class="sh">Why the demo didn&#39;t ship</div><ul><li><strong>Approval owners, not models:</strong> In a hypothetical document-exception assistant, security asks where it runs, data owners ask who approved the document use, and risk asks who reviews a wrong exception. &quot;The demo worked. The model was fine. It still did not ship&quot; (<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=36s" target="_blank" rel="noopener">0:36</a>–<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=68s" target="_blank" rel="noopener">1:08</a>)</li><li><strong>Four decision areas:</strong> Data (who owns and grants use), model risk (which review applies), third-party risk (the full provider and hosting chain), and audit (can you reconstruct input, config, what the reviewer saw, and who approved) (<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=68s" target="_blank" rel="noopener">1:08</a>–<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=168s" target="_blank" rel="noopener">2:48</a>)</li><li><strong>Discovery questions:</strong> Where the data lives and who approves reading it, who has blocked similar projects, who signs the risk review. By Friday, every decision owner should know the project exists (<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=297s" target="_blank" rel="noopener">4:57</a>–<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=352s" target="_blank" rel="noopener">5:52</a>)</li></ul><div class="sh">Shrinking scope and authority</div><ul><li><strong>Shadow, draft, shrink:</strong> Sit with the analyst and write down the real sequence, then reduce it to three lines: review docs → draft exception → analyst submits. Take that draft to control owners so they can cross things out (<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=352s" target="_blank" rel="noopener">5:52</a>–<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=457s" target="_blank" rel="noopener">7:37</a>)</li><li><strong>Autonomy ladder:</strong> Suggest → draft → act with approval → act within limits. Each step changes which controls must work. Start at the lowest rung that creates value and use override and failure data to decide on more authority (<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=519s" target="_blank" rel="noopener">8:39</a>–<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=695s" target="_blank" rel="noopener">11:35</a>) (overlaps with today&#39;s Michele Grant talk)</li></ul><div class="sh">Evidence pack</div><ul><li><strong>Five files:</strong> Intended use, data lineage, failure modes (detection, fallback, owner), results by segment (clean docs, scans, rare exceptions, new types; lead with the weakest), and controls. Preserve prompts, model version and reviewer actions, because re-calling the model won&#39;t reproduce the answer (<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=695s" target="_blank" rel="noopener">11:35</a>–<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=814s" target="_blank" rel="noopener">13:34</a>)</li><li><strong>Friday score:</strong> Five yes/no questions. 4–5 yeses means a credible path to ship, 3 means owners and dates are needed, and 0–2 means re-scope before committing (<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=814s" target="_blank" rel="noopener">13:34</a>–<a href="https://www.youtube.com/watch?v=3ZlQk4-knWM&amp;t=870s" target="_blank" rel="noopener">14:30</a>)</li></ul></div></article><article class="it full" id="v-Fe4aSMXsOZ4" data-title="Every Building Is a Balance Sheet: Spatial Memory for Real-World Assets — Jordi Spranger, Spranic" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+Y+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4" target="_blank" rel="noopener">Every Building Is a Balance Sheet: Spatial Memory for Real-World Assets — Jordi Spranger, Spranic</a></h3><div class="meta">AI Engineer · Jordi Spranger, Spranic (with Neo4j) · uploaded 13 Oct, 7:30 PM IST · 10:29</div><div class="verdict v-skim"><b>Verdict:</b> skim from 5:53 — the kitchen change-detection demo is the interesting part; the rest is market framing for a startup founded in June 2026.</div><div class="sh">The problem</div><ul><li><strong>Books vs buildings:</strong> Real estate is about $400T globally (residential ~$300T, commercial ~$60T). Loans and insurance are re-booked quarterly, but the building itself is often only inspected every few years, around financing events (<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=32s" target="_blank" rel="noopener">0:32</a>–<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=140s" target="_blank" rel="noopener">2:20</a>)</li><li><strong>Underinsurance:</strong> He cites research on 1,500 properties finding ~70% underinsured, plus about $4T of US commercial mortgages that depend on building state (<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=143s" target="_blank" rel="noopener">2:23</a>–<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=178s" target="_blank" rel="noopener">2:58</a>)</li></ul><div class="sh">Spatial memory demo</div><ul><li><strong>Walk = memory:</strong> An off-the-shelf sensor scans a conference hall in about a minute of walking. Recognised objects go into a Neo4j graph, and repeat walks are aligned on a time axis (<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=178s" target="_blank" rel="noopener">2:58</a>–<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=292s" target="_blank" rel="noopener">4:52</a>)</li><li><strong>Ledger questions:</strong> What changed, when, with which source observation, and who needs to know (e.g. expired fire extinguishers) (<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=292s" target="_blank" rel="noopener">4:52</a>–<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=353s" target="_blank" rel="noopener">5:53</a>)</li><li><strong>Kitchen scanned twice:</strong> Natural-language queries (&quot;where can I heat myself&quot; → the radiator; &quot;a glass to drink from&quot;), plus change detection that found three moved chairs, with references back to the capture (<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=353s" target="_blank" rel="noopener">5:53</a>–<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=444s" target="_blank" rel="noopener">7:24</a>)</li></ul><div class="sh">Use case</div><ul><li><strong>Insurance:</strong> Baseline scan at policy start, a re-scan at renewal, and premiums priced on verified upkeep. He cites 1 in 3 commercial buildings booked with the wrong construction class and 35–60% hurricane-premium deductions for certified buildings (<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=444s" target="_blank" rel="noopener">7:24</a>–<a href="https://www.youtube.com/watch?v=Fe4aSMXsOZ4&amp;t=600s" target="_blank" rel="noopener">10:00</a>)</li></ul></div></article><article class="it full" id="v-SHvwutPSeZg" data-title="Judge a Transaction by the Company It Keeps — Somya Rai &amp; MD Sharique, EXL" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=SHvwutPSeZg" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+J+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=SHvwutPSeZg" target="_blank" rel="noopener">Judge a Transaction by the Company It Keeps — Somya Rai &amp; MD Sharique, EXL</a></h3><div class="meta">AI Engineer · Somya Rai &amp; MD Sharique, EXL · uploaded 13 Oct, 6:30 PM IST · 20:28</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — one of the most concrete production-ML talks in a while; skim from 5:22 if you only want the engineering.</div><div class="repeat">🔁 Repeat: &#39;inference / serving&#39; — seen 26 times before. New here: low-latency GNN serving via cached user/merchant embeddings and edge-level prediction (60 GB → 2–3 GB).</div><div class="sh">Why tabular features hit a ceiling</div><ul><li><strong>Same row, different score:</strong> A transaction with 198 engineered features scores 0.04. When the model can also see that its user, merchant and two linked transactions were flagged as fraud in the last hour, the same row scores 0.91. &quot;The signal was in the edges&quot; (<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=16s" target="_blank" rel="noopener">0:16</a>–<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=60s" target="_blank" rel="noopener">1:00</a>)</li><li><strong>Two portfolios, fixed alert budget:</strong> Card-present fraud runs at 0.05% (1 in 2,000) and online at 0.6% (12× higher), so they train two models. Analysts only review the top 0.5–1.5%, so the target is precision at fixed K, not AUC (<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=66s" target="_blank" rel="noopener">1:06</a>–<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=125s" target="_blank" rel="noopener">2:05</a>)</li><li><strong>Feature engineering plateau:</strong> Going from 40 to 87 features moved TPR only 35.5→36.6, and online gained about 1 point from ~200 features, because every feature is a function of the same row (<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=132s" target="_blank" rel="noopener">2:12</a>–<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=197s" target="_blank" rel="noopener">3:17</a>)</li></ul><div class="sh">How the graph model works</div><ul><li><strong>Feeds XGBoost, doesn&#39;t replace it:</strong> GNN embeddings go into the same gradient-boosted model. Result: a 27–33% relative TPR lift at the same alert rate, about $65M projected annualised incremental fraud capture, and 3 ms P99 (<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=251s" target="_blank" rel="noopener">4:11</a>–<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=300s" target="_blank" rel="noopener">5:00</a>)</li><li><strong>Sampling without breaking the graph:</strong> A soft fraud target (0.5% card / 6% online, about 10× natural) keeps every selected user&#39;s full history. A fraudster&#39;s genuine transactions stay in as hard negatives, and user degree (11.5–14) matches inference (<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=383s" target="_blank" rel="noopener">6:23</a>–<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=509s" target="_blank" rel="noopener">8:29</a>)</li><li><strong>Leakage-free by construction:</strong> Each calendar month is its own disjoint graph and only earlier-timestamped neighbours are aggregated. 202 features (73 user / 109 transaction / 20 merchant), including 32 fraud-specific derived ones such as 5-min/1-h/24-h velocity and impossible-travel rate (<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=509s" target="_blank" rel="noopener">8:29</a>–<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=692s" target="_blank" rel="noopener">11:32</a>)</li><li><strong>Mean + max + std aggregation:</strong> With three normal neighbours (~0.1) and one fraud-ring neighbour (0.92), the mean is 0.32 and dilutes the ring, while the max keeps 0.92. 128-dim embeddings were the sweet spot (<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=692s" target="_blank" rel="noopener">11:32</a>–<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=817s" target="_blank" rel="noopener">13:37</a>)</li></ul><div class="sh">Results, explainability, serving</div><ul><li><strong>Numbers:</strong> Card TPR 36%→48% (+33%, $5.6M), online 48%→61% (+27%, $35.4M). Edge attribution on 200 flagged cases shows transaction-velocity edges dominate (0.94 card / 0.62 online), and merchant edges matter more online (<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=827s" target="_blank" rel="noopener">13:47</a>–<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=935s" target="_blank" rel="noopener">15:35</a>)</li><li><strong>3 ms serving:</strong> Embeddings are cached and online scoring runs only the new transaction&#39;s two-layer forward pass. Pinning math-library thread pools to 1 cut latency from 30 ms to 1 ms. Node-level caching needed 60 GB and TPR fell 48→44% with a 1-day lag, so they moved to edge prediction (2–3 GB, ~20× smaller). Final: 2.3 ms median, 3.1 ms P99 (<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=1000s" target="_blank" rel="noopener">16:40</a>–<a href="https://www.youtube.com/watch?v=SHvwutPSeZg&amp;t=1200s" target="_blank" rel="noopener">20:00</a>)</li></ul></div></article><article class="it full" id="v-dYh7TQkuYFE" data-title="I Believe Everything My Agents Tell Me: Three Levels of Review — Corey Gallon, Rexmore" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=dYh7TQkuYFE" target="_blank" rel="noopener"><img src="'+d+'" srcset="'+U+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=dYh7TQkuYFE" target="_blank" rel="noopener">I Believe Everything My Agents Tell Me: Three Levels of Review — Corey Gallon, Rexmore</a></h3><div class="meta">AI Engineer · Corey Gallon, Rexmore · uploaded 13 Oct, 5:30 PM IST · 12:25</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a concrete, reusable review recipe with real costs and failure stories; the skills are open source at gallon.me (<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=695s" target="_blank" rel="noopener">11:35</a>).</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 15 times before. New here: verification applied beyond code (bookkeeping and a legal letter), with per-review token and time costs.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 9 times before. New here: a fan-out/fan-in pattern of identically tasked agents reconciled against a control total.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 4 times before. New here: the three review levels are released as open-source skills (write-up at gallon.me).</div><div class="sh">Why agents need review</div><ul><li><strong>Error rate in his own work:</strong> After 107B+ tokens through agents in 2026, his session analysis found an agent made a consequential error in about 4 of 10 sessions (before review, not in final outputs). Three failure modes: overstating what was done, wrong facts, wrong reasoning (<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=3s" target="_blank" rel="noopener">0:03</a>–<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=82s" target="_blank" rel="noopener">1:22</a>)</li><li><strong>Level 1, verify the deliverable:</strong> The job spec names the exact file, location and a check command; the agent must end with &quot;artifact verified&quot; plus a file fingerprint, or &quot;artifact missing&quot; with the reason. The dispatching agent then runs the check itself, and &quot;done&quot; alone is not accepted (<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=77s" target="_blank" rel="noopener">1:17</a>–<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=121s" target="_blank" rel="noopener">2:01</a>)</li><li><strong>Level 2, independent extraction:</strong> Two agents get identical instructions and work blind to each other, citing sources for every fact; a third agent compares them line by line against the source and never forces a match (<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=121s" target="_blank" rel="noopener">2:01</a>–<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=159s" target="_blank" rel="noopener">2:39</a>)</li><li><strong>Level 3, adversarial review:</strong> The agent first tags every claim as measured, checked, inferred or assumed. Then cold persona reviewers with no prior context look for faults, and after revision brand-new reviewers check the final version (<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=159s" target="_blank" rel="noopener">2:39</a>–<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=239s" target="_blank" rel="noopener">3:59</a>)</li></ul><div class="sh">Three real cases</div><ul><li><strong>Memory leak (9 GB):</strong> A sub-agent quietly used the wrong profiling tool and said &quot;done&quot;. With Level 1 tasking, a later sub-agent honestly reported a failed build (25 compiler errors) as partial work (19 min, ~16M tokens). Cold reviewers also caught a wrongly blamed library and an overstated &quot;fully fixed&quot; claim, so the PR went up with honest numbers and was merged (~6M tokens) (<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=239s" target="_blank" rel="noopener">3:59</a>–<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=412s" target="_blank" rel="noopener">6:52</a>)</li><li><strong>A year of accounting:</strong> Monthly statement balances served as control totals. Two independent extractions plus a reconciler caught 56 differences, and the year balanced to the penny (~20 min, 7.5M tokens) (<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=412s" target="_blank" rel="noopener">6:52</a>–<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=536s" target="_blank" rel="noopener">8:56</a>)</li><li><strong>Demand letter:</strong> The drafter&#39;s self-check passed, but the litigator and vendor&#39;s-counsel personas both found a 3-year auto-renewal that had renewed less than 3 weeks earlier. The drafter had even deleted a line flagging it. Verdict: do not send (15 min, 13M tokens) (<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=536s" target="_blank" rel="noopener">8:56</a>–<a href="https://www.youtube.com/watch?v=dYh7TQkuYFE&amp;t=695s" target="_blank" rel="noopener">11:35</a>)</li></ul></div></article><article class="it full" id="v-RsWyIQoJkHY" data-title="Formula 1 Just Had a Production Incident (Short)" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=RsWyIQoJkHY" target="_blank" rel="noopener"><img src="'+p+'" srcset="'+q+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=RsWyIQoJkHY" target="_blank" rel="noopener">Formula 1 Just Had a Production Incident (Short)</a></h3><div class="meta">Better Stack · Better Stack · uploaded 13 Oct, 9:30 PM IST · 1:39</div><div class="verdict v-skim"><b>Verdict:</b> skim — a fun 1:39 incident story with no tooling content.</div><ul><li><strong>The bug:</strong> In the first wet race for the 2026 cars at Sepang, the power-unit controller&#39;s wet-weather mode hit a low-speed edge case that left cars stuck in idle. Verstappen triggered it first, and eight other cars were crawling too (<a href="https://www.youtube.com/watch?v=RsWyIQoJkHY&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=RsWyIQoJkHY&amp;t=43s" target="_blank" rel="noopener">0:43</a>)</li><li><strong>Hotfix mid-race:</strong> The race was red-flagged, and the FIA coded a patch lifting the wet-weather power reduction in affected zones and shipped it to all 11 teams. The race restarted 50 minutes later (<a href="https://www.youtube.com/watch?v=RsWyIQoJkHY&amp;t=43s" target="_blank" rel="noopener">0:43</a>–<a href="https://www.youtube.com/watch?v=RsWyIQoJkHY&amp;t=60s" target="_blank" rel="noopener">1:00</a>)</li><li><strong>Drivers&#39; reactions:</strong> Bearman: &quot;I didn&#39;t even know the FIA could control our throttle pedal&quot;; Piastri had never seen a race delayed by a bug. Better Stack&#39;s takeaway: the kind of edge case you only see in production (<a href="https://www.youtube.com/watch?v=RsWyIQoJkHY&amp;t=60s" target="_blank" rel="noopener">1:00</a>–<a href="https://www.youtube.com/watch?v=RsWyIQoJkHY&amp;t=99s" target="_blank" rel="noopener">1:39</a>)</li></ul></div></article><article class="it full" id="v-BjmoXpgbfhQ" data-title="AI Can Mod ANY Game (Short)" data-channel="Better Stack" data-verdict="skip"><a class="th" href="https://www.youtube.com/watch?v=BjmoXpgbfhQ" target="_blank" rel="noopener"><img src="'+w+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-skip">skip</span><h3><a href="https://www.youtube.com/watch?v=BjmoXpgbfhQ" target="_blank" rel="noopener">AI Can Mod ANY Game (Short)</a></h3><div class="meta">Better Stack · Better Stack · uploaded 13 Oct, 5:30 PM IST · 1:59</div><div class="verdict v-skip"><b>Verdict:</b> skip — a 2-minute recap of yesterday&#39;s &quot;Black Ops 3 Zombies in GTA 5&quot; video.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 40 times before. New here: nothing much; this is a clip of yesterday&#39;s Universal Modder video.</div><ul><li><strong>What it is (repeat):</strong> Universal Modder by Rehan Sheikh (ex-fal) is a Claude Code plugin made of skills, a CLI and a knowledge base. Examples: Minecraft inside GTA 5 and CoD zombies rebuilt in Minecraft (<a href="https://www.youtube.com/watch?v=BjmoXpgbfhQ&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=BjmoXpgbfhQ&amp;t=47s" target="_blank" rel="noopener">0:47</a>)</li><li><strong>The loop (repeat):</strong> Search the knowledge base → recon (the CLI fingerprints the engine, anti-cheat and save location) → back up saves → read the code → build one slice → test in-game → write a field note. Art comes from fal (<a href="https://www.youtube.com/watch?v=BjmoXpgbfhQ&amp;t=47s" target="_blank" rel="noopener">0:47</a>–<a href="https://www.youtube.com/watch?v=BjmoXpgbfhQ&amp;t=83s" target="_blank" rel="noopener">1:23</a>)</li><li><strong>Knowledge base:</strong> 117 game notes plus 65 technique notes, mostly written by Claude Code and OpenCode, and users contribute via PRs. It stops hard at anti-cheat. Kotaku called it a &quot;plague of vibecoded mashups&quot; (<a href="https://www.youtube.com/watch?v=BjmoXpgbfhQ&amp;t=83s" target="_blank" rel="noopener">1:23</a>–<a href="https://www.youtube.com/watch?v=BjmoXpgbfhQ&amp;t=119s" target="_blank" rel="noopener">1:59</a>)</li></ul></div></article></div>',1))])}const j=m(C,[["render",W]]);export{N as __pageData,j as default};
